// invalid is the value of aria-invalid: "true" for the field to blame, absent for the others (a bare attribute is read as false).
func invalid(yes bool) any {
	if yes {
		return "true"
	}
	return false
}

// stateText says where the managed llama.cpp stands, in a sentence.
func (m Managed) stateText() string {
	model := m.Model
	if model == "" {
		model = "モデル未選択"
	}
	switch m.State {
	case "running":
		return "動いています（モデル: " + model + "）。画像・動画を作る前に止まり、次の LLM の呼び出しで自動で起動します"
	case "starting":
		return "起動しています（モデル: " + model + "。読み込みに時間がかかります）"
	case "stopped":
		return "導入済みです（モデル: " + model + "）。最初の LLM の呼び出しで自動で起動します（モデルの読み込みに少し待ちます）"
	case "failed":
		return "起動に失敗しました（モデル: " + model + "）"
	case "unsupported":
		return "この PC では使えません"
	}
	return "まだ使えません"
}

func keyPlaceholder(d Data) string {
	switch {
	case d.KeyUnreadable:
		return "キーストアを読めません"
	case d.KeyConfigured && d.KeyHint != "":
		return "設定済み（末尾 " + d.KeyHint + "）。空欄なら変更しません"
	case d.KeyConfigured:
		return "設定済み。空欄なら変更しません"
	}
	return "空欄（キー不要のサーバー）"
}

